package org.example.medistock.model;

import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;

/**
 * Notification entity owned by Member 4 (Expiry, Notifications & Reports).
 * Represents system alerts generated by expiry monitors, low stock checks,
 * and exchange event notifications.
 */
public class Notification {

    public enum NotificationType {
        EXPIRY_WARNING,
        BATCH_EXPIRED,
        LOW_STOCK,
        EXCHANGE_EVENT,
        SYSTEM_ALERT
    }

    public enum Priority {
        HIGH,
        NORMAL,
        LOW
    }

    private String notificationId;
    private String pharmacyId;
    private String title;
    private String message;
    private NotificationType type;
    private Priority priority;
    private boolean isRead;
    private LocalDateTime createdAt;

    public Notification() {
        this.createdAt = LocalDateTime.now();
        this.isRead = false;
        this.priority = Priority.NORMAL;
    }

    public Notification(String notificationId, String pharmacyId, String title,
                        String message, NotificationType type, Priority priority) {
        this.notificationId = notificationId;
        this.pharmacyId = pharmacyId;
        this.title = title;
        this.message = message;
        this.type = type;
        this.priority = priority;
        this.isRead = false;
        this.createdAt = LocalDateTime.now();
    }

    public Notification(String notificationId, String pharmacyId, String title,
                        String message, NotificationType type, Priority priority,
                        boolean isRead, LocalDateTime createdAt) {
        this.notificationId = notificationId;
        this.pharmacyId = pharmacyId;
        this.title = title;
        this.message = message;
        this.type = type;
        this.priority = priority;
        this.isRead = isRead;
        this.createdAt = createdAt != null ? createdAt : LocalDateTime.now();
    }

    public String getNotificationId() {
        return notificationId;
    }

    public void setNotificationId(String notificationId) {
        this.notificationId = notificationId;
    }

    public String getPharmacyId() {
        return pharmacyId;
    }

    public void setPharmacyId(String pharmacyId) {
        this.pharmacyId = pharmacyId;
    }

    public String getTitle() {
        return title;
    }

    public void setTitle(String title) {
        this.title = title;
    }

    public String getMessage() {
        return message;
    }

    public void setMessage(String message) {
        this.message = message;
    }

    public NotificationType getType() {
        return type;
    }

    public void setType(NotificationType type) {
        this.type = type;
    }

    public Priority getPriority() {
        return priority;
    }

    public void setPriority(Priority priority) {
        this.priority = priority;
    }

    public boolean isRead() {
        return isRead;
    }

    public void setRead(boolean read) {
        isRead = read;
    }

    public LocalDateTime getCreatedAt() {
        return createdAt;
    }

    public void setCreatedAt(LocalDateTime createdAt) {
        this.createdAt = createdAt;
    }

    public String getFormattedTimestamp() {
        return createdAt != null ? createdAt.format(DateTimeFormatter.ofPattern("dd MMM HH:mm:ss")) : "N/A";
    }

    public String getPriorityBadgeStyle() {
        if (priority == null) return "-fx-background-color: #e2e8f0; -fx-text-fill: #475569;";
        return switch (priority) {
            case HIGH -> "-fx-background-color: #fee2e2; -fx-text-fill: #b91c1c; -fx-font-weight: bold; -fx-padding: 3 8; -fx-background-radius: 12;";
            case NORMAL -> "-fx-background-color: #fef3c7; -fx-text-fill: #92400e; -fx-font-weight: bold; -fx-padding: 3 8; -fx-background-radius: 12;";
            case LOW -> "-fx-background-color: #e0f2fe; -fx-text-fill: #0369a1; -fx-font-weight: bold; -fx-padding: 3 8; -fx-background-radius: 12;";
        };
    }

    public String getTypeBadgeStyle() {
        if (type == null) return "-fx-background-color: #e2e8f0; -fx-text-fill: #475569;";
        return switch (type) {
            case BATCH_EXPIRED, EXPIRY_WARNING -> "-fx-background-color: #ffedd5; -fx-text-fill: #c2410c; -fx-padding: 3 8; -fx-background-radius: 12;";
            case LOW_STOCK -> "-fx-background-color: #fef9c3; -fx-text-fill: #854d0e; -fx-padding: 3 8; -fx-background-radius: 12;";
            case EXCHANGE_EVENT -> "-fx-background-color: #ede9fe; -fx-text-fill: #6d28d9; -fx-padding: 3 8; -fx-background-radius: 12;";
            case SYSTEM_ALERT -> "-fx-background-color: #ccfbf1; -fx-text-fill: #0f766e; -fx-padding: 3 8; -fx-background-radius: 12;";
        };
    }

    @Override
    public String toString() {
        return String.format("[%s] [%s] %s: %s", priority, type, title, message);
    }
}
